source='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    row_seps = [r for r, row in enumerate(grid) if len(set(row)) == 1]
    col_seps = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    def segments(n, seps):
        out=[]; start=0
        for x in seps:
            if x > start: out.append(list(range(start, x)))
            start=x+1
        if start<n: out.append(list(range(start,n)))
        return out
    rs, cs = segments(h,row_seps), segments(w,col_seps)
    cells=[grid[r][c] for rr in rs for r in rr for cc in cs for c in cc]
    bg=Counter(cells).most_common(1)[0][0]
    best=None; best_score=-1
    for rr in rs:
        for cc in cs:
            score=sum(grid[r][c] != bg for r in rr for c in cc)
            if score > best_score:
                best, best_score=(rr,cc),score
    out=[row[:] for row in grid]
    sr,sc=best
    for rr in rs:
        for cc in cs:
            if len(rr)==len(sr) and len(cc)==len(sc):
                for i,r in enumerate(rr):
                    for j,c in enumerate(cc):
                        out[r][c]=grid[sr[i]][sc[j]]
    return out
